import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';

function DynamicGallery() {
  const [photos, setPhotos] = useState([]);

  useEffect(() => {
    supabase.from('gallery').select('*').eq('published', true).order('sort_order').order('created_at', { ascending: false }).then(({ data }) => {
      setPhotos(data ?? []);
    });
  }, []);

  if (photos.length === 0) return null;

  return (
    <div className="container" style={{ paddingTop: 40, paddingBottom: 40 }}>
      <h2 className="text-center" style={{ marginBottom: 24 }}>Latest from SDV</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 12 }}>
        {photos.map((photo) => (
          <div key={photo.id} style={{ borderRadius: 8, overflow: 'hidden', background: '#f5f5f5' }}>
            <a href={photo.image_url} target="_blank" rel="noopener noreferrer">
              <img
                src={photo.image_url}
                alt={photo.title || ''}
                style={{ width: '100%', height: 180, objectFit: 'cover', display: 'block' }}
              />
            </a>
            {photo.title && (
              <div style={{ padding: '8px 10px', fontSize: 13, fontWeight: 600 }}>{photo.title}</div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default DynamicGallery;
