import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';

function DynamicEvents() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    supabase.from('events').select('*').eq('published', true).gte('event_date', new Date().toISOString()).order('event_date').limit(6).then(({ data }) => {
      setEvents(data ?? []);
    });
  }, []);

  if (events.length === 0) return null;

  const fmt = (d) => new Date(d).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div id="events" className="container" style={{ paddingTop: 40, paddingBottom: 40 }}>
      <h2 className="text-center" style={{ marginBottom: 24 }}>Upcoming Events</h2>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 700, margin: '0 auto' }}>
        {events.map((event) => (
          <div key={event.id} style={{ display: 'flex', gap: 20, padding: 20, background: '#f9f9f9', borderRadius: 10, borderLeft: '4px solid #c8a96e' }}>
            {event.event_date && (
              <div style={{ minWidth: 60, textAlign: 'center' }}>
                <div style={{ fontSize: 28, fontWeight: 700, lineHeight: 1, color: '#c8a96e' }}>{new Date(event.event_date).getDate()}</div>
                <div style={{ fontSize: 12, textTransform: 'uppercase', color: '#666' }}>{new Date(event.event_date).toLocaleString('en', { month: 'short' })}</div>
              </div>
            )}
            <div>
              <h3 style={{ margin: 0, fontSize: 17, fontWeight: 700 }}>{event.title}</h3>
              {event.location && <div style={{ fontSize: 13, color: '#888', marginTop: 4 }}>📍 {event.location}</div>}
              {event.description && <p style={{ fontSize: 14, color: '#555', marginTop: 8, marginBottom: 0 }}>{event.description}</p>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default DynamicEvents;
