import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';

function MembershipForm() {
  const [form, setForm]       = useState({ name: '', email: '', phone: '', speciality: '', bio: '' });
  const [saving, setSaving]   = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError]     = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault(); setSaving(true); setError('');
    const { error: err } = await supabase.from('members').insert({ ...form, status: 'pending' });
    setSaving(false);
    if (err) { setError('Something went wrong. Please try again.'); return; }
    setSuccess(true);
    setForm({ name: '', email: '', phone: '', speciality: '', bio: '' });
  };

  if (success) {
    return (
      <div style={{ textAlign: 'center', padding: '40px 20px', background: '#f0f9f0', borderRadius: 12 }}>
        <div style={{ fontSize: 48 }}>✅</div>
        <h3 style={{ marginTop: 16 }}>Application Received!</h3>
        <p style={{ color: '#555' }}>Thank you for applying to SDV NRW e.V. We will review your application and contact you soon.</p>
      </div>
    );
  }

  const field = (key, label, type = 'text', required = false) => (
    <div style={{ marginBottom: 16 }}>
      <label style={{ display: 'block', fontWeight: 600, marginBottom: 6, fontSize: 14 }}>{label}{required && ' *'}</label>
      <input
        type={type} required={required} value={form[key]}
        onChange={(e) => setForm({ ...form, [key]: e.target.value })}
        style={{ width: '100%', padding: '10px 14px', border: '1px solid #ddd', borderRadius: 8, fontSize: 14 }}
      />
    </div>
  );

  return (
    <div id="membership" className="container" style={{ paddingTop: 40, paddingBottom: 60, maxWidth: 600 }}>
      <h2 className="text-center" style={{ marginBottom: 8 }}>Join SDV NRW e.V.</h2>
      <p className="text-center" style={{ color: '#666', marginBottom: 32 }}>Fill in the form below and we will get back to you shortly.</p>
      <form onSubmit={handleSubmit} style={{ background: '#f9f9f9', padding: 32, borderRadius: 12 }}>
        {field('name',       'Full Name',   'text', true)}
        {field('email',      'Email',       'email', true)}
        {field('phone',      'Phone')}
        {field('speciality', 'Speciality / Profession')}
        <div style={{ marginBottom: 16 }}>
          <label style={{ display: 'block', fontWeight: 600, marginBottom: 6, fontSize: 14 }}>About yourself</label>
          <textarea
            rows={3} value={form.bio}
            onChange={(e) => setForm({ ...form, bio: e.target.value })}
            style={{ width: '100%', padding: '10px 14px', border: '1px solid #ddd', borderRadius: 8, fontSize: 14 }}
          />
        </div>
        {error && <p style={{ color: 'red', fontSize: 14 }}>{error}</p>}
        <button type="submit" disabled={saving}
          style={{ width: '100%', padding: '12px', background: '#2563a8', color: '#fff', border: 'none', borderRadius: 8, fontSize: 16, fontWeight: 700, cursor: saving ? 'not-allowed' : 'pointer' }}>
          {saving ? 'Submitting…' : 'Submit Application'}
        </button>
      </form>
    </div>
  );
}

export default MembershipForm;
