import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';

function AppHero() {
  const [heading, setHeading] = useState('Connecting Sudanese Hearts in Germany');
  const [body, setBody]       = useState('SDV NRW e.V. supports Sudanese immigrants and their families in North Rhine-Westphalia — providing community, culture, and care.');

  useEffect(() => {
    supabase.from('settings').select('key,value').in('key', ['hero_heading','hero_body']).then(({ data }) => {
      if (!data) return;
      data.forEach(({ key, value }) => {
        if (key === 'hero_heading' && value) setHeading(value);
        if (key === 'hero_body'    && value) setBody(value);
      });
    });
  }, []);

  return (
    <div id="hero" className="heroBlock">
      <div className="hero-inner">
        <div className="hero-badge">Est. 1982 &bull; Essen, NRW</div>
        <h1>{heading}</h1>
        <p>{body}</p>
        <div className="hero-buttons">
          <a href="#about" className="btn-hero-primary">Discover More</a>
          <a href="#contact" className="btn-hero-outline">Contact Us</a>
        </div>
      </div>
      <div className="hero-scroll">Scroll</div>
    </div>
  );
}

export default AppHero;
